    (Parameters) -> State when
        Parameters :: ed25519_sign_init_parameters(), State :: ed25519ph_sign_state();
    (Parameters) -> State when
        Parameters :: ed448_sign_init_parameters(), State :: ed448ph_sign_state().

eddsa_sign_init({ed25519ph, Key}) ->
    eddsa_sign_init({ed25519ph, Key, <<>>});
eddsa_sign_init({ed25519ph, Key, Context}) when is_binary(Context), byte_size(Context) =< 255 ->
    {ed25519ph_sign, libdecaf_nif:ed25519ph_keypair_sign_init(eddsa_ed25519_keypair(Key), Context)};
eddsa_sign_init({ed448ph, Key}) ->
    eddsa_sign_init({ed448ph, Key, <<>>});
eddsa_sign_init({ed448ph, Key, Context}) when is_binary(Context), byte_size(Context) =< 255 ->
    {ed448ph_sign, libdecaf_nif:ed448ph_keypair_sign_init(eddsa_ed448_keypair(Key), Context)};
eddsa_sign_init(_) ->
    erlang:error(badarg).

-doc """
Add another original-message chunk and return a new signing state.

Chunks accept iodata. Large updates yield to the scheduler; completed updates do not retain the
input chunks. The original state remains reusable for branching. Signing and verification states are
distinct.
""".
-doc #{group => <<"EdDSA API">>}.
-spec eddsa_sign_update
    (State, Message) -> NextState when
        State :: ed25519ph_sign_state(), Message :: message(), NextState :: ed25519ph_sign_state();
    (State, Message) -> NextState when
        State :: ed448ph_sign_state(), Message :: message(), NextState :: ed448ph_sign_state().

eddsa_sign_update({ed25519ph_sign, State}, Message) ->
    {ed25519ph_sign, libdecaf_nif:ed25519ph_sign_update(State, Message)};
eddsa_sign_update({ed448ph_sign, State}, Message) ->
    {ed448ph_sign, libdecaf_nif:ed448ph_sign_update(State, Message)};
eddsa_sign_update(_, _) ->
    erlang:error(badarg).

-doc """
Verify a signature over an original message using the same algorithm and context as signing.

Parameters contain a public key, public/secret pair, or opaque keypair. Return `false` for a
correctly sized signature that fails verification; malformed keys, signatures, or parameters raise
`badarg`. Message input accepts iodata.

```erlang
Keypair = libdecaf:eddsa_keypair(ed448),
Signature = libdecaf:eddsa_sign({ed448, Keypair, <<"protocol/v1">>}, <<"message">>),
true = libdecaf:eddsa_verify({ed448, Keypair, <<"protocol/v1">>}, Signature, <<"message">>).
```
""".
-doc #{group => <<"EdDSA API">>}.
-spec eddsa_verify
    (Parameters, Signature, Message) -> Valid when
        Parameters :: ed25519_verify_parameters(),
        Signature :: ed25519_signature(),
        Message :: message(),
        Valid :: boolean();
    (Parameters, Signature, Message) -> Valid when
        Parameters :: ed448_verify_parameters(),
        Signature :: ed448_signature(),
        Message :: message(),
        Valid :: boolean().

eddsa_verify({ed25519, Key}, Signature, Message) ->
    libdecaf_nif:ed25519_verify(Signature, eddsa_ed25519_public_key(Key), iolist_to_binary(Message), 0, no_context);
eddsa_verify({ed25519ctx, Key}, Signature, Message) ->
    eddsa_verify({ed25519ctx, Key, <<>>}, Signature, Message);
eddsa_verify({ed25519ctx, Key, Context}, Signature, Message) when is_binary(Context), byte_size(Context) =< 255 ->
    libdecaf_nif:ed25519_verify(Signature, eddsa_ed25519_public_key(Key), iolist_to_binary(Message), 0, Context);
eddsa_verify({ed25519ph, Key}, Signature, Message) ->
    eddsa_verify({ed25519ph, Key, <<>>}, Signature, Message);
eddsa_verify({ed25519ph, Key, Context}, Signature, Message) when is_binary(Context), byte_size(Context) =< 255 ->
    libdecaf_nif:ed25519_verify_prehash(Signature, eddsa_ed25519_public_key(Key), iolist_to_binary(Message), Context);
eddsa_verify({ed448, Key}, Signature, Message) ->
    eddsa_verify({ed448, Key, <<>>}, Signature, Message);
eddsa_verify({ed448, Key, Context}, Signature, Message) when is_binary(Context), byte_size(Context) =< 255 ->
    libdecaf_nif:ed448_verify(Signature, eddsa_ed448_public_key(Key), iolist_to_binary(Message), 0, Context);
eddsa_verify({ed448ph, Key}, Signature, Message) ->
    eddsa_verify({ed448ph, Key, <<>>}, Signature, Message);
eddsa_verify({ed448ph, Key, Context}, Signature, Message) when is_binary(Context), byte_size(Context) =< 255 ->
    libdecaf_nif:ed448_verify_prehash(Signature, eddsa_ed448_public_key(Key), iolist_to_binary(Message), Context);
eddsa_verify(_, _, _) ->
    erlang:error(badarg).

-doc """
Verify the accumulated original message against the retained signature, key, and context. The input
state is unchanged; repeated finalization returns the same result. Return `false` if verification
fails.
""".
-doc #{group => <<"EdDSA API">>}.
-spec eddsa_verify_final
    (State) -> Valid when
        State :: ed25519ph_verify_state(), Valid :: boolean();
    (State) -> Valid when
        State :: ed448ph_verify_state(), Valid :: boolean().

eddsa_verify_final({ed25519ph_verify, State}) ->
    libdecaf_nif:ed25519ph_verify_final(State);
eddsa_verify_final({ed448ph_verify, State}) ->
    libdecaf_nif:ed448ph_verify_final(State);
eddsa_verify_final(_) ->
    erlang:error(badarg).

-doc """
Start streaming verification with Ed25519ph or Ed448ph.

Use `{Algorithm, PublicKeyOrKeypair}` with an optional third context field, matching the signing
parameters. The native state retains the key, context, signature and prehash. Updates and
finalization leave their input reusable. Pure Ed25519, Ed25519ctx, and Ed448 are one-shot only.

```erlang
Keypair = libdecaf:eddsa_keypair(ed25519),
S0 = libdecaf:eddsa_sign_init({ed25519ph, Keypair, <<"protocol/v1">>}),
S1 = libdecaf:eddsa_sign_update(S0, [<<"hello ">>, <<"world">>]),
Signature = libdecaf:eddsa_sign_final(S1),
V0 = libdecaf:eddsa_verify_init({ed25519ph, Keypair, <<"protocol/v1">>}, Signature),
V1 = libdecaf:eddsa_verify_update(V0, <<"hello world">>),
true = libdecaf:eddsa_verify_final(V1).
```
""".
-doc #{group => <<"EdDSA API">>}.
-spec eddsa_verify_init
    (Parameters, Signature) -> State when
        Parameters :: ed25519_verify_init_parameters(),
        Signature :: ed25519_signature(),
        State :: ed25519ph_verify_state();
    (Parameters, Signature) -> State when
        Parameters :: ed448_verify_init_parameters(), Signature :: ed448_signature(), State :: ed448ph_verify_state().

eddsa_verify_init({ed25519ph, Key}, Signature) ->
    eddsa_verify_init({ed25519ph, Key, <<>>}, Signature);
eddsa_verify_init({ed25519ph, Key, Context}, Signature) when is_binary(Context), byte_size(Context) =< 255 ->
    {ed25519ph_verify, libdecaf_nif:ed25519ph_verify_init(Signature, eddsa_ed25519_public_key(Key), Context)};
eddsa_verify_init({ed448ph, Key}, Signature) ->
    eddsa_verify_init({ed448ph, Key, <<>>}, Signature);
eddsa_verify_init({ed448ph, Key, Context}, Signature) when is_binary(Context), byte_size(Context) =< 255 ->
    {ed448ph_verify, libdecaf_nif:ed448ph_verify_init(Signature, eddsa_ed448_public_key(Key), Context)};
eddsa_verify_init(_, _) ->
    erlang:error(badarg).

-doc """
Add another original-message chunk and return a new verification state.

Chunks accept iodata. Large updates yield to the scheduler; completed updates do not retain the
input chunks. The original state remains reusable for branching. Signing and verification states are
distinct.
""".
-doc #{group => <<"EdDSA API">>}.
-spec eddsa_verify_update
    (State, Message) -> NextState when
        State :: ed25519ph_verify_state(), Message :: message(), NextState :: ed25519ph_verify_state();
    (State, Message) -> NextState when
        State :: ed448ph_verify_state(), Message :: message(), NextState :: ed448ph_verify_state().

eddsa_verify_update({ed25519ph_verify, State}, Message) ->
    {ed25519ph_verify, libdecaf_nif:ed25519ph_verify_update(State, Message)};
eddsa_verify_update({ed448ph_verify, State}, Message) ->
    {ed448ph_verify, libdecaf_nif:ed448ph_verify_update(State, Message)};
eddsa_verify_update(_, _) ->
    erlang:error(badarg).

%%%=============================================================================
%%% Hash API functions
%%%=============================================================================

-doc """
Hash input using an algorithm atom or initialization parameter tuple.

Tuple fields match `hash_init/1`. For TupleHash, input is a list of separate elements.

```erlang
Output = libdecaf:hash({parallelhash128, 32, 8192, <<"orders/v1">>}, <<"invoice-42">>),
State = libdecaf:hash_update(libdecaf:hash_init({parallelhash128, 32, 8192, <<"orders/v1">>}), <<"invoice-42">>),
Output = libdecaf:hash_final(State).
```
""".
-doc #{group => <<"Hash API">>}.
-spec hash(Parameters, Input) -> Output when
    Parameters :: hash_parameters(), Input :: input() | tuple_input(), Output :: binary().
hash(Parameters, Input) ->
    libdecaf_nif:hash(Parameters, Input).

-doc """
Return the digest or authentication tag at the length chosen during initialization.

This leaves the state reusable. KMAC, TupleHash, and ParallelHash include the chosen
length in their computation: initialize at the desired length instead of truncating
a longer result. SHA-2, SHA-3, and legacy Keccak return digest prefixes when shortened.

```erlang
Key = binary:copy(<<42>>, 32),
State0 = libdecaf:hash_init({kmac128, 16, Key}),
State1 = libdecaf:hash_update(State0, <<"invoice-42">>),
Tag = libdecaf:hash_final(State1),
16 = byte_size(Tag),
Tag = libdecaf:hash({kmac128, 16, Key}, <<"invoice-42">>).
```
""".
-doc #{group => <<"Hash API">>}.
-spec hash_final(HashState) -> Output when
    HashState :: hash_state(), Output :: binary().
hash_final(HashState) ->
    libdecaf_nif:hash_final(HashState).

-doc """
Initialize a hash using an algorithm atom or a parameter tuple.

Tuple fields put the algorithm first, then output length and construction-specific options.
For example, `{kmac128, 32, Key, <<"orders/v1">>}` selects a 32-byte KMAC tag.
The output length belongs to the state; finish with `hash_final/1`.

Parameter forms (`L` is output bytes, `S` is customization, and `B` is block bytes):

| Algorithms | Parameters |
| --- | --- |
| SHA-2, SHA-3, fixed Keccak | `Algorithm` or `{Algorithm, L}` |
| SHAKE, Keccak XOF | `{Algorithm, L}` |
| cSHAKE | `{Algorithm, L}` or `{Algorithm, L, FunctionName, S}` |
| KMAC, HopMAC | `{Algorithm, L, Key}` or `{Algorithm, L, Key, S}` |
| KT | `Algorithm`, `{Algorithm, L}`, or `{Algorithm, L, S}` |
| TurboSHAKE | `Algorithm`, `{Algorithm, L}`, or `{Algorithm, L, Domain}` |
| TupleHash | `{Algorithm, L}` or `{Algorithm, L, S}` |
| ParallelHash | `{Algorithm, L, B}` or `{Algorithm, L, B, S}` |

SHA-2, SHA-3, and fixed Keccak permit prefixes up to the full digest size.
KT and TurboSHAKE default to 32 bytes at strength 128 and 64 at strength 256.
TurboSHAKE's domain is an integer in `1..127`, defaulting to `16#1F`.
ParallelHash's positive block size affects the digest; update boundaries do not.
Blocks are processed serially in constant memory. Keys and customization accept
iodata; omitted customization and function names are empty.

```erlang
State0 = libdecaf:hash_init({sha3_256, 16}),
State1 = libdecaf:hash_update(State0, <<"abc">>),
<<"3A985DA74FE225B2045C172D6BD390BD">> = binary:encode_hex(libdecaf:hash_final(State1)).
```
""".
-doc #{group => <<"Hash API">>}.
-spec hash_init(Parameters) -> Result when
    Parameters :: hash_parameters(), Result :: hash_state().
hash_init(Parameters) ->
    libdecaf_nif:hash_init(Parameters).

-doc """
Add input to a hash and return a new state.

Input accepts iodata. For TupleHash, each call adds **one complete tuple element**:
two calls with `<<"a">>` and `<<"bc">>` differ from two calls with `<<"ab">>` and `<<"c">>`.
An empty element counts; an empty one-shot list contains no elements.
The original state remains reusable, so it can be used to hash different suffixes.
""".
-doc #{group => <<"Hash API">>}.
-spec hash_update(HashState, Input) -> NewHashState when
    HashState :: hash_state(), Input :: input(), NewHashState :: hash_state().
hash_update(HashState, Input) ->
    libdecaf_nif:hash_update(HashState, Input).

-doc """
Compute a parallel hash from initialization parameters and input.

Uses the same framing and produces the same bytes as `hash/2`.
Parallelism applies to independent leaves, without changing the algorithm.

```erlang
Input = binary:copy(<<"abc">>, 10000),
Output = libdecaf:parallel_hash(kt128, Input),
Output = libdecaf:hash(kt128, Input).
```
""".
-doc #{group => <<"Hash API">>}.
-spec parallel_hash(Parameters, Input) -> Output when
    Parameters :: parallel_hash_parameters(), Input :: input(), Output :: binary().
parallel_hash(Parameters, Input) ->
    parallel_wait(
        libdecaf_nif:parallel_hash(Parameters, Input),
        fun libdecaf_nif:parallel_hash_continue/1,
        fun(FinalState, _Length) -> libdecaf_nif:parallel_hash_final(FinalState) end
    ).

-doc """
Return the configured hash output without changing the input state.

```erlang
State = libdecaf:parallel_hash_update(libdecaf:parallel_hash_init(kt128), <<"abc">>),
Digest = libdecaf:parallel_hash_final(State),
Digest = libdecaf:hash(kt128, <<"abc">>).
```
""".
-doc #{group => <<"Hash API">>}.
-spec parallel_hash_final(State) -> Output when
    State :: parallel_hash_state(), Output :: binary().
parallel_hash_final(State) ->
    libdecaf_nif:parallel_hash_final(State).

-doc """
Initialize a parallel Hash state.

Accepts the same parameter forms as `hash_init/1` for KT128/KT256,
HopMAC128/HopMAC256, and ParallelHash128/ParallelHash256.
Other algorithms raise `badarg`. KT and HopMAC use 8192-byte leaves;
ParallelHash uses its configured block size. States remain immutable.

```erlang
S0 = libdecaf:parallel_hash_init({parallelhash128, 32, 8192}),
S1 = libdecaf:parallel_hash_update(S0, <<"invoice-42">>),
Output = libdecaf:parallel_hash_final(S1).
```
""".
-doc #{group => <<"Hash API">>}.
-spec parallel_hash_init(Parameters) -> State when
    Parameters :: parallel_hash_parameters(), State :: parallel_hash_state().
parallel_hash_init(Parameters) ->
    libdecaf_nif:parallel_hash_init(Parameters).

-doc """
Add input to a parallel Hash state and return its new state.

Input accepts iodata. Large inputs are processed concurrently using the
application's worker pool, while results are combined in input order.
The previous state remains reusable. Without a worker pool, the call still
completes using the caller's dirty scheduler.
""".
-doc #{group => <<"Hash API">>}.
-spec parallel_hash_update(State, Input) -> NewState when
    State :: parallel_hash_state(), Input :: input(), NewState :: parallel_hash_state().
parallel_hash_update(State, Input) ->
    parallel_wait(
        libdecaf_nif:parallel_hash_update(State, Input),
        fun libdecaf_nif:parallel_hash_continue/1,
        fun(FinalState, _Length) -> libdecaf_nif:parallel_hash_final(FinalState) end
    ).

%%%=============================================================================
%%% XOF API functions
%%%=============================================================================

-doc """
Compute parallel XOF output from initialization parameters and input.

Uses the same framing and produces the same bytes as `xof/3`.
Parallelism applies to independent leaves, without changing the algorithm.

```erlang
Input = binary:copy(<<"abc">>, 10000),
Output = libdecaf:parallel_xof(kt128, Input, 64),
Output = libdecaf:xof(kt128, Input, 64).
```
""".
-doc #{group => <<"XOF API">>}.
-spec parallel_xof(Parameters, Input, OutputLength) -> Output when
    Parameters :: parallel_xof_parameters(), Input :: input(), OutputLength :: output_length(), Output :: binary().
parallel_xof(Parameters, Input, OutputLength) ->
    parallel_wait(
        libdecaf_nif:parallel_xof(Parameters, Input, OutputLength),
        fun libdecaf_nif:parallel_xof_continue/1,
        fun(FinalState, Length) ->
            {_Next, Output} = libdecaf_nif:parallel_xof_squeeze(FinalState, Length),
            Output
        end
    ).

-doc """
Add input to a parallel XOF state and return its new state.

Input accepts iodata. Large inputs are processed concurrently using the
application's worker pool, while results are combined in input order.
The previous state remains reusable. Without a worker pool, the call still
completes using the caller's dirty scheduler.
""".
-doc #{group => <<"XOF API">>}.
-spec parallel_xof_absorb(State, Input) -> NewState when
    State :: parallel_xof_state(), Input :: input(), NewState :: parallel_xof_state().
parallel_xof_absorb(State, Input) ->
    parallel_wait(
        libdecaf_nif:parallel_xof_absorb(State, Input),
        fun libdecaf_nif:parallel_xof_continue/1,
        fun(FinalState, Length) ->
            {_Next, Output} = libdecaf_nif:parallel_xof_squeeze(FinalState, Length),
            Output
        end
    ).

-doc """
Initialize a parallel XOF state.

Accepts the same parameter forms as `xof_init/1` for KT128/KT256,
HopMAC128/HopMAC256, and ParallelHashXOF128/ParallelHashXOF256.
Other algorithms raise `badarg`. KT and HopMAC use 8192-byte leaves;
ParallelHash uses its configured block size. States remain immutable.

```erlang
S0 = libdecaf:parallel_xof_init({parallelhashxof128, 8192}),
S1 = libdecaf:parallel_xof_absorb(S0, <<"invoice-42">>),
{_S2, Output} = libdecaf:parallel_xof_squeeze(S1, 32).
```
""".
-doc #{group => <<"XOF API">>}.
-spec parallel_xof_init(Parameters) -> State when
    Parameters :: parallel_xof_parameters(), State :: parallel_xof_state().
parallel_xof_init(Parameters) ->
    libdecaf_nif:parallel_xof_init(Parameters).

-doc """
Read output and return `{NextState, Output}`.

The returned state can keep squeezing, but cannot absorb further input.
The input state remains reusable. Output lengths are in bytes.

```erlang
S0 = libdecaf:parallel_xof_absorb(libdecaf:parallel_xof_init(kt128), <<"abc">>),
{S1, First} = libdecaf:parallel_xof_squeeze(S0, 32),
{_S2, Next} = libdecaf:parallel_xof_squeeze(S1, 32),
Combined = <<First/binary, Next/binary>>,
Combined = libdecaf:xof(kt128, <<"abc">>, 64).
```
""".
-doc #{group => <<"XOF API">>}.
-spec parallel_xof_squeeze(State, OutputLength) -> Result when
    State :: parallel_xof_state(), OutputLength :: output_length(), Result :: {parallel_xof_state(), binary()}.
parallel_xof_squeeze(State, OutputLength) ->
    libdecaf_nif:parallel_xof_squeeze(State, OutputLength).

-doc """
Return `OutputLength` bytes using XOF initialization parameters and input.

The parameter atom or tuple is identical to `xof_init/1`; output length is supplied
separately. For TupleHashXOF, input is a list of separate elements.

```erlang
Parameters = {cshake128, <<>>, <<"orders/v1">>},
Output = libdecaf:xof(Parameters, <<"invoice-42">>, 32),
State = libdecaf:xof_absorb(libdecaf:xof_init(Parameters), <<"invoice-42">>),
{_Next, Output} = libdecaf:xof_squeeze(State, 32).
```
""".
-doc #{group => <<"XOF API">>}.
-spec xof(Parameters, Input, OutputLength) -> Output when
    Parameters :: xof_parameters(),
    Input :: input() | tuple_input(),
    OutputLength :: output_length(),
    Output :: binary().
xof(Parameters, Input, OutputLength) ->
    libdecaf_nif:xof(Parameters, Input, OutputLength).

-doc """
Add input to an absorbing XOF and return a new state.

Input accepts iodata. For TupleHashXOF each call adds one whole tuple element;
for all other algorithms calls concatenate message bytes. After squeezing starts,
the returned squeezing state rejects further input, even after a zero-byte squeeze.
The original absorbing state remains reusable.
""".
-doc #{group => <<"XOF API">>}.
-spec xof_absorb(XOFState, Input) -> NewXOFState when
    XOFState :: xof_state(), Input :: input(), NewXOFState :: xof_state().
xof_absorb(XOFState, Input) ->
    libdecaf_nif:xof_absorb(XOFState, Input).

-doc """
Initialize an XOF using an algorithm atom or a parameter tuple.

Tuple fields put the algorithm first, followed by its construction-specific options.
Choose customization, keys, block sizes, or domain separation here; output length
is chosen later with `xof_squeeze/2`.

| Algorithms | Parameters |
| --- | --- |
| SHAKE, Keccak XOF | `Algorithm` |
| cSHAKE | `Algorithm` or `{Algorithm, FunctionName, Customization}` |
| KMACXOF, HopMAC | `{Algorithm, Key}` or `{Algorithm, Key, Customization}` |
| KT, TupleHashXOF | `Algorithm` or `{Algorithm, Customization}` |
| TurboSHAKE | `Algorithm` or `{Algorithm, Domain}` |
| ParallelHashXOF | `{Algorithm, BlockSize}` or `{Algorithm, BlockSize, Customization}` |

Use `kmacxof128`, `kmacxof256`, `tuplehashxof128`, `tuplehashxof256`,
`parallelhashxof128`, and `parallelhashxof256` selectors for these XOF variants. They produce different output from their
length-bound hash variants. Other XOF families are SHAKE, cSHAKE, Keccak XOF,
KT, TurboSHAKE, and HopMAC, each at strength 128 or 256.
Function names, keys, and customization accept iodata; empty cSHAKE strings yield
SHAKE output. TurboSHAKE uses an integer domain in `1..127`, default `16#1F`.
Keep KMACXOF and HopMAC states private like their keys.

```erlang
State0 = libdecaf:xof_init({cshake128, <<>>, <<"orders/v1">>}),
State1 = libdecaf:xof_absorb(State0, <<"invoice-42">>),
{_State2, Output} = libdecaf:xof_squeeze(State1, 32),
Output = libdecaf:xof({cshake128, <<>>, <<"orders/v1">>}, <<"invoice-42">>, 32).
```
""".
-doc #{group => <<"XOF API">>}.
-spec xof_init(Parameters) -> Result when
    Parameters :: xof_parameters(), Result :: xof_state().
xof_init(Parameters) ->
    libdecaf_nif:xof_init(Parameters).

-doc """
Return `{NextState, Output}` with the next `Length` bytes of an XOF stream.

Continue with `NextState` to read subsequent bytes. Squeezing the same input state
again repeats those bytes, because states are immutable. A zero-byte squeeze still
enters the output phase. Customization is already stored by the initializer.

```erlang
State0 = libdecaf:xof_init(shake128),
State1 = libdecaf:xof_absorb(State0, [<<"a">>, <<"bc">>]),
{State2, First} = libdecaf:xof_squeeze(State1, 16),
{_State3, Second} = libdecaf:xof_squeeze(State2, 16),
Output = <<First/binary, Second/binary>>,
Output = libdecaf:xof(shake128, <<"abc">>, 32).
```
""".
-doc #{group => <<"XOF API">>}.
-spec xof_squeeze(XOFState, Length) -> Result when
    XOFState :: xof_state(), Length :: output_length(), Result :: {xof_state(), binary()}.
xof_squeeze(XOFState, Length) ->
    libdecaf_nif:xof_squeeze(XOFState, Length).

%%%=============================================================================
%%% Sponge PRNG API functions
%%%=============================================================================

-doc """
Generate `Length` cryptographically random bytes without managing a PRNG state.

The generator is seeded automatically from operating-system entropy and
reseeded periodically. If native entropy is unavailable, it uses
`crypto:strong_rand_bytes/1` to obtain seed bytes. An entropy-source failure
raises an exception. A zero-byte request returns `<<>>`.

For an explicitly seeded or deterministic stream, use `m:libdecaf_spongerng`.

```erlang
Token = libdecaf:strong_rand_bytes(32),
32 = byte_size(Token),
<<>> = libdecaf:strong_rand_bytes(0).
```
""".
-doc #{group => <<"Sponge PRNG API">>}.
-spec strong_rand_bytes(Length) -> Output when Length :: non_neg_integer(), Output :: binary().
strong_rand_bytes(Length) ->
    case libdecaf_nif:strong_rand_bytes(Length) of
        need_seed ->
            libdecaf_nif:strong_rand_bytes(Length, crypto:strong_rand_bytes(64));
        Output ->
            Output
    end.

%%%=============================================================================
%%% Deprecated API
%%%=============================================================================

-doc """
Derive an X25519 scalar from a Ed25519 secret seed.
""".
-doc #{
    group => <<"Deprecated API">>, deprecated => <<"Use libdecaf_nif:ed25519_convert_private_key_to_x25519/1 instead.">>
}.
-spec ed25519_convert_private_key_to_x25519(SecretKey) -> Result when
    SecretKey :: libdecaf_nif:ed25519_secret_key(), Result :: libdecaf_nif:x25519_scalar().
ed25519_convert_private_key_to_x25519(SecretKey) ->
    libdecaf_nif:ed25519_convert_private_key_to_x25519(SecretKey).

-doc """
Convert an encoded Ed25519 public key to its X25519 public-key encoding.
